import json
from pathlib import Path
p=Path(__file__).parent/'authored-notes.json'
n=json.loads(p.read_text(encoding='utf-8'))
replacements={
0:[('有两万六千多个参数，不多。','有两万六千多个参数，不多，不多。'),('把它们调整到合适的位置','我们当时就是这样说的：希望把它们调整到一个合适的位置')],
1:[('最后产生一个结果。','最后产生一个结果。输入一个东西，经过这些运算，产生最后的结果。')],
2:[('设置合适的值最好。','两种情况都会容易产生问题，设置一个合适的值最好。'),('每一层有多少神经元呢？','然后每一层有多少个神经元呢？像这个隐藏层，每一层有多少个神经元？')],
3:[('所以一定要把图片数字化。','它不能接收别的东西，只能接收数字。所以我们肯定要把图片数字化。'),('它也是一个数字。','这个十六进制值，不就是一个数字吗？'),('于是可以把这个值作为第一个数字，表示第一个像素点，再接第二个、第三个，一共1600个像素点。','于是可以把这个值作为第一个数字，表示第一个像素点。再接第二个像素点、第三个像素点，是不是一共写1600个像素点？是不是可以这样？把这组数字是不是就可以作为输入？'),('就是激活值越高，它越亮。','就是激活值。那个值越高，它就越亮，就是这个意思。'),('这里每个节点往后传递的值，就是我们的输入。','每个节点要往后传递一个值，输出一个值。这里向后面传递的结果，就是我们的输入，这一块能理解吗？')],
4:[('具体每个负责什么，不是我们人为规定的，也规定不了。','这个神经元负责什么、另一个神经元负责什么，都不知道，谁都不知道。最多最多只能管有多少层、每层有多少神经元，具体每个神经元负责什么，不是我们人为规定的，也规定不了。'),('这里所谓活跃和不活跃，其实就是数字大小，只是说起来更直观一些。','数字很小，就说明它不活跃；数字越大，就说明它很活跃，往后传递的数字很大。这里所谓活跃和不活跃，其实就是数字大小，只是这样说让你听起来更直观一些。')],
5:[('慢慢算也能算完。','慢慢算也能算完，慢慢算就是了。'),('它乘以 x₁，x₁从哪里来？','随机出来一个 w₁，随机出来的数字乘以 x₁。那么 x₁从哪里来呢？'),('数学基础稍弱的同学可能要多次暂停，不断想、不断消化，才能理解这一课。','数学基础稍弱的同学可能要多次暂停，不断去想，不断去想，不断去消化，才能理解这一课。'),('每一个都跟前面全部连接，这就叫全连接。','每一个神经元跟前面所有神经元都有连接，看到了吗？都是这样的，所以叫全连接。你看，每一个神经元，跟前面全部都是有连接的。'),('最后再加上 b，b 也是随机的。','一直加下去，最后再加上一个 b，b 也是随机的。')],
6:[('第二个、第三个神经元也是同样的算法。','好，又来这一层，每一个都是随机的。第二个神经元同样的算法，第三个神经元同样的算法。'),('下一层又有自己的 w₁、w₂，一直加到 w₁₆x₁₆','下一层又来，有它自己的 w₁，有自己的权重，又是随机的。然后是 w₂，一直加到 w₁₆x₁₆'),('这样，这一层所有神经元就全部算出来了。','所以每一个算出的结果是不一样的。这样是不是就算出了这一层所有神经元？是不是全部算出来了？'),('这里可以再暂停想一想。','每一层的神经元有多少个权重，等于什么？就等于上一层有多少个输出。这里可以再暂停想一想。')],
7:[('这里就是输入、输出、输入、输出。','它就是接收数字，计算过后输出。它自己有智能吗？像我们人一样有意识吗？你说意识从哪儿来？这里就是输入、输出、输入、输出。')],
8:[('输入节点数量就能缩小一点。','输入节点数量就能缩小一点，为什么一定整张图一起输入呢？'),('就做裁剪、压缩，把它压到这个大小。','做什么呢？做裁剪、压缩，把它压到这个分辨率。这些都是题外话。')],
9:[('这个意义纯粹是人为定义的。','我就给它人为定义，纯粹是人为定义。这些东西都是人为定义的，人为给它定义意义。'),('把一组数据转换成百分比形式。','它可以把任何一组数据都转换成百分比形式。'),('有兴趣可以了解它怎么实现。','有兴趣可以了解这个工具怎么实现。不管那组数据有多大，它都可以转换成百分比格式。'),('你可以这样想象：','明白我的意思吗？你就可以这样想象：')],
10:[('听好这句话：当输入固定时','听好这句话，当输入是固定的时候，听好这句话：当输入固定时'),('这是首先要认识的名词。','这就是你第一个要认识的名词。先让它跑一次，给它一个数据，让它跑一次，后面我们再调。'),('这些是人来调吗？肯定不是，它会自己调。','调整每一个旋钮，都对整个神经网络的输出结果造成一定影响。这个是人来调吗？肯定不是人来调，它会自己调。'),('这种影响是传递的。','然后它的输出结果又会影响后面，这种影响是传递性的，最终整个网络的权重、偏置都会影响输出。')],
11:[('我们从第一隐藏层开始算。','我们要算权重、偏置，就从这一层开始算。它有多少个权重、偏置，能反应过来吗？先看第一个神经元。'),('权重就是16×16；偏置还是一个节点一个，共16个。','权重就是16×16。偏置 b 有几个？也是16个，对不对？所以再加16。'),('再加10个偏置。','再加上输出层的偏置，10个。'),('也有两万六千多个参数，不多。','也有两万六千多个参数，不多，不多。')],
12:[('它表示来自哪一层。','它表示的是层，来自第几层。不是平方，也不是立方，不是这个意思。'),('a₇⁽²⁾。','a₇⁽²⁾，意思是第二层的第七个神经元。'),('这仍是单个神经元的计算。','只是把 xᵢ 变成 aᵢ，上面写 L−1，来自上一层的输入。其他没有任何变化，还是单个神经元。')],
13:[('基础弱的同学不用纠结，因为我要引出的主要内容不是数学公式。','数学基础不好的同学不用纠结，因为我讲这个的主要目的不是讲数学公式，我马上要引出一个东西。'),('这个结果表示当前层每个神经元的输出','算出来的结果就是这一列，是一个矩阵。这个结果表示当前层每个神经元的输出'),('要说明的主要就是这一点。','这是为什么要用 GPU 来计算的原因，就在这里。我就想跟你说这一点。')],
14:[('调整权重，调整偏置。','调整权重，调整偏置，调的就是这个东西。')]
}
for i,pairs in replacements.items():
    for a,b in pairs:
        assert a in n[i]['text'],(i,a)
        n[i]['text']=n[i]['text'].replace(a,b,1)
n[10]['visual']=n[10]['visual'].replace('整个网络的隐藏层与输出层被框选，旁边便签写“所有的权重”。','画面显示整个网络的隐藏层与输出层，旁边便签标题为“前向传播”。')
p.write_text(json.dumps(n,ensure_ascii=False,indent=2),encoding='utf-8')
print('edited characters',sum(len(x['text']) for x in n))
